function ySampleReviews(p){if(!/^p\d+$|^sku-/.test(p.id))return[];let wood=p.cat==='地板板材',tile=p.cat==='瓷砖石材';return[
 {id:p.id+'-r1',score:5,user:'林**',text:tile?'老板帮我核对了同批次和留缝，怕补砖色差还提醒留两片备用，沟通很细。':wood?'木纹小样先拿回家看了两天，商家也提醒先核对基层和门口高差，比较负责。':'客服把尺寸和安装条件解释得很清楚，主动让我复核后再下单，这点挺负责。',aspect:'服务细心',sample:true},
 {id:p.id+'-r2',score:5,user:'周**',text:'东西和确认的规格一致，包装也仔细。安装另计的费用提前说明了，没有到现场才加钱。',aspect:'规格与质量',sample:true},
 {id:p.id+'-r3',score:4,user:'许**',text:'整体符合需求，但到货比原约定晚了两天。商家后来重新约了送货，希望以后能早点主动通知。',aspect:'交期沟通',sample:true},
 {id:p.id+'-r4',score:4,user:'陈**',text:'实物可以，保修说明写得太简单，人工和材料谁承担没讲清。我补问以后才拿到具体范围，建议先看清再买。',aspect:'质保待改进',sample:true}];}
function yReviews(id){let p=productBy(id);return p?[...ySampleReviews(p),...(YS.reviews[id]||[])]:[];}
function yRating(id){let r=yReviews(id);return r.length?r.reduce((s,a)=>s+a.score,0)/r.length:0;}
function yRatingButton(id){let rating=yRating(id);return `<button class="rating-chip" data-y="reviews" data-id="${esc(id)}" aria-label="查看${esc(productBy(id)?.name)}评分与评论"><span class="star-meter" aria-hidden="true"><span>★★★★★</span><i style="width:${rating*20}%">★★★★★</i></span><b>${rating?rating.toFixed(1):'暂无'}</b></button>`;}
