function yShowReviews(id){let p=productBy(id);if(!p)return;let reviews=yReviews(id),rating=yRating(id);modal('评分与评论 · '+p.name,`<div class="review-summary"><strong>${rating?rating.toFixed(1):'—'}</strong><div><b>满分 5 星</b><p>${reviews.length} 条记录 · ${reviews.filter(r=>!r.sample).length} 条本机体验评价</p></div></div><div class="notice">展示用评价为示例文案，不代表真实成交或认证用户。新提交内容仅保存在本机，正式上线需交易与身份核验。</div><div class="review-list">${reviews.map(r=>`<article><div><b>${esc(r.user)}</b><span>${'★'.repeat(Math.floor(r.score))} ${r.score.toFixed(1)}</span><small>${r.sample?'示例评价':'本机体验评价 · 未核验交易'}</small></div><p>${esc(r.text)}</p><span class="tag">${esc(r.aspect||'用户分享')}</span></article>`).join('')}</div><form id="yj-review" data-product="${p.id}"><h3>写下体验</h3><label class="field">评分<select name="score">${[5,4.5,4,3.5,3,2,1].map(v=>`<option>${v}</option>`).join('')}</select></label><label class="field">哪里好、哪里需要改善<textarea name="text" required minlength="8" maxlength="800" placeholder="具体说明规格、质量、配送、服务或保修，避免只写“很好”。"></textarea></label><button class="primary" type="submit">保存本机体验评价</button></form>`,true);}
