 const root=state.view==='space'?$('#space-page'):$('#content');
 for(const tr of root.querySelectorAll('tbody tr')){if(tr.querySelector('.rating-chip'))continue;let p=null;for(const el of tr.querySelectorAll('[data-id]')){let id=el.dataset.id;p=productBy(id);if(!p){let o=E.orders.find(x=>x.id===id)||E.items.find(x=>x.id===id)||E.inquiries.find(x=>x.id===id);if(o)p=productBy(o.product);}if(p)break;}if(p)tr.cells[0]?.insertAdjacentHTML('beforeend',yRatingButton(p.id));}
