 'support-contact':el=>{let c=YS.cases.find(c=>c.id===el.dataset.id);if(!c)return;if(!c.contactSent){notify('售后协调请求：'+YD.support.find(s=>s.id===c.kind).title+' · '+c.id,[c.role,'company'],'customer');c.contactSent=true;c.state='已发本地协调请求';c.messages.push({who:'bot',text:'已向'+roles[c.role].name+'和主要交付责任方发出本地项目协调请求，正在等待其回复。尚未接通外部客服或电话；回复后会在本工单继续整理解决方案。'});let t=E.tickets.find(t=>t.id===c.ticket);if(t){t.state='处理中';t.assigned=roles[c.role].name;}}else c.messages.push({who:'bot',text:'协调请求已登记，目前'+c.state+'。可以补充证据、催办或请责任方在其工作台提交方案。'});audit('售后协调请求',c.id);ysave();render();},
 'support-evidence':el=>{let c=YS.cases.find(c=>c.id===el.dataset.id);if(!c)return;openForm('补充问题、凭证与诉求',[field('note','问题位置、订单、时间、凭证编号和希望的解决方式','textarea',[],{wide:true}),field('file','照片 / 订单 / 检测凭证（500 KB 内）','file')],{},d=>{c.messages.push({who:'user',text:d.note});let t=E.tickets.find(t=>t.id===c.ticket);if(t){t.messages.push({role:state.role,text:d.note,time:TODAY});if(d.file)t.evidence.push(d.file);}addRequest('售后补充资料',c.id+' · '+d.note);});},
